let additionalDesigns=[];
const beforeAdditional=render;
render=function(){document.getElementById('additional-course-schema')?.remove();document.getElementById('additional-description')?.remove();const n=Number(location.hash.split('/')[1]);if(!location.hash.startsWith('#program/')||![1,12,13,14].includes(n))return beforeAdditional();document.getElementById('app').innerHTML=integratedShell('additional-program',heading('Program design','Loading…'),model.role);fetch('data/additional-programs.json').then(r=>{if(!r.ok)throw Error('Design unavailable');return r.json();}).then(items=>{if(location.hash!=='#program/'+n)return;additionalDesigns=items;const p=items.find(x=>x.program===n),c=p.commercial;const list=a=>'<ul>'+a.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>';document.getElementById('app').innerHTML=integratedShell('additional-program',heading(p.title,'Scholarion Academy · Draft for academic review')+`<section class="card prose"><a href="#catalog">All programs</a> · <a href="#program-studio">Instructor design studio</a><p>${esc(p.competencies[0].text)}</p><p>${p.totalWeeks} weeks · ${p.courses.length} ten-week course block(s) · ${p.weeklyHours?p.weeklyHours.join('–')+' hours/week proposed':'Workload pending faculty confirmation'}</p><p>Start: ${esc(c.startDate||'Unconfigured')} · Fee: ${c.fee===null?'Unconfigured':esc(String(c.fee))} · Online delivery; live schedule pending</p><button class="button" disabled>Apply Now — not open</button> <a class="button secondary" href="brochures/program-${n}.pdf" download>Download draft brochure (PDF)</a><h2>Program overview</h2><p>This pathway develops evidence-based practice through guided design, synthetic scenarios and a final defense. Each course is ten weeks; a multi-course pathway takes the full sequence.</p><p>These previews describe proposed learning. Enrollment, assessed completion and badge issuance are not enabled for these designs.</p><h2>What you will learn</h2>${list(p.competencies.map(x=>x.text))}<h2>Who it is for</h2><p>${esc(p.audience)}. ${esc(p.prerequisites)}</p><h2>Curriculum</h2>${p.courses.map(b=>`<h3>${esc(b.id)} · ${esc(b.title)} · 10 weeks</h3>${b.modules.map(m=>`<details><summary>Week ${m.week}: ${esc(m.title)}</summary>${list(m.outcomes.map(o=>o.text))}<p>Activity: ${esc(m.activity.student)}</p></details>`).join('')}<p>Final assessment design: ${esc(b.finalAssessment)}</p>`).join('')}<h2>Projects and capstone</h2>${list(p.projects.map(x=>x.title+' — '+x.status))}<p>${esc(p.capstone)}</p><h3>Proposed review rubric</h3>${list(p.rubric.map(r=>r.criterion+': '+r.points+' points'))}<h2>Tools and data</h2><p>Tool selections, versions and educational licenses await verification. No vendor affiliation or endorsement is implied. Only synthetic or properly licensed datasets with reviewed data cards may be used. No shared master API keys are distributed.</p><h2>Learning experience</h2><p>Mentorship, office hours, peer discussion and recordings with transcripts are proposed, not scheduled services. AI coaching must not complete graded work.</p><h2>Faculty</h2><p>Lead faculty: ${esc(p.faculty)}. Biography pending; additional mentors are not confirmed.</p><h2>Certificate and badges</h2><p>${esc(p.credential.title)}; proposed Open Badges 3.0 credential. ${p.credential.perCourse?'Individual course certificates and a bundle badge after both courses.':''} ${p.learningHours?'Estimated learning hours: '+p.learningHours.join('–')+'.':'Learning hours require confirmation.'} No CEUs claimed. Eligibility and issuance require approved assessment policies.</p><a href="#credentials">View credential previews</a><h2>Career support</h2><p>Portfolio guidance, resume reviews and mock interviews require confirmed staffing. No placement or salary outcomes are promised.</p><h2>Fees, financing and dates</h2><p>Fees, currency, installment terms, discounts, sponsorship, deadlines and time zone are unconfigured. Real payment is disabled. No seat reservation can be made from this preview.</p><h2>How to apply</h2><p>Planned sequence: application → admission review → sandbox seat reservation → orientation. Admissions wiring for these programs is pending approved intake configuration.</p><h2>Teams and advisor contact</h2><a href="#help">Open local Support for a program or team inquiry</a><p>Advisor scheduling, phone and email are not configured.</p><h2>Frequently asked questions</h2><details><summary>Can I take a course independently?</summary><p>Program #13 is designed for standalone courses and a sequential bundle. Approved enrollment rules are pending.</p></details><details><summary>How do transfers and optional activities work?</summary><p>${esc(p.dependencyNotes)} Optional enrichment never substitutes for required assessment.</p></details><details><summary>What are the refund and technical requirements?</summary><p>Approved refund, tax and withdrawal terms and a verified tool-access checklist must be supplied before enrollment opens.</p></details><h2>Remaining release requirements</h2>${list(p.gaps)}</section>`,model.role);bind();normalizeWorkspace();document.title=p.title+' · Scholarion Academy';const schema=document.createElement('script');schema.id='additional-course-schema';schema.type='application/ld+json';schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'Course',name:p.title,description:'Draft curriculum preview; not open for enrollment.',provider:{'@type':'Organization',name:'Scholarion Academy'},hasPart:p.courses.map(c=>({'@type':'Course',name:c.title,timeRequired:'P10W'}))});document.head.appendChild(schema);const meta=document.createElement('meta');meta.id='additional-description';meta.name='description';meta.content=p.title+' — draft '+p.totalWeeks+'-week program design at Scholarion Academy. Enrollment not open.';document.head.appendChild(meta);}).catch(e=>{document.getElementById('app').textContent=e.message;});};
render();
